(()=>{
const icons=['','🌰','🌱','🥬','🧺','🎁'],names=['빈칸','씨앗','새싹','채소','바구니','나눔 상자'];let selected=-1,busy=false,message='';
const dialog=document.createElement('dialog');dialog.className='merge-game';dialog.setAttribute('aria-label','씨앗 머지 놀이터');document.body.append(dialog);
const menu=document.createElement('button');menu.textContent='🎲 씨앗 머지 놀이터';(document.querySelector('#compactQuiz')||document.querySelector('.compact-menu-grid')).append(menu);menu.onclick=()=>window.openMergeGame();
function draw(){const g=state.mergeGame;dialog.innerHTML=`<div class="merge-heading"><h2>씨앗 머지 놀이터</h2><button data-merge-close aria-label="놀이터 닫기">×</button></div><p>같은 그림을 하나씩 눌러 합쳐요. 나눔 상자까지 키워 보세요!</p><div class="merge-chain">🌰 → 🌱 → 🥬 → 🧺 → 🎁</div><small>첫 완성 10코인 · 한국 날짜 기준 하루 1회. 이후에는 보상 없이 즐겨요. 농장 재고는 사용하지 않아요.</small>${!window.classroomActive?'<p>체험 학생 또는 학급으로 입장하면 놀이와 보너스를 저장할 수 있어요.</p><button data-merge-entry>체험·학급 입장</button>':g?`<div class="merge-board">${g.board.map((v,i)=>`<button data-merge-cell="${i}" aria-label="${i+1}번 ${names[v]}" aria-pressed="${selected===i}" ${busy||!v||g.complete?'disabled':''}>${icons[v]||'·'}<small>${names[v]}</small></button>`).join('')}</div><p>${g.complete?(g.reward?'🎉 나눔 상자 완성! 10코인을 받았어요.':'🎉 완성! 오늘 보너스는 이미 받았어요.'):`${g.moves}번 합쳤어요 · ${selected<0?'첫 번째 그림을 고르세요.':'같은 그림을 하나 더 고르세요.'}`}</p><button data-merge-start ${busy?'disabled':''}>${g.complete?'한 판 더':'새 판 시작'}</button>`:'<button data-merge-start>놀이 시작</button>'}<p role="status" class="merge-message"></p>`;dialog.querySelector('.merge-message').textContent=message}
async function act(action){if(busy)return;busy=true;message='저장 중…';draw();try{const ok=await schoolAction(action);message=ok?'':'저장을 확인하지 못했어요. 연결과 수업 상태를 확인해 주세요.';if(ok)selected=-1}finally{busy=false;draw()}}
window.openMergeGame=()=>{document.querySelector('.compact-menu')?.close();selected=-1;message='';draw();if(!dialog.open)dialog.showModal()};
dialog.onclick=e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.hasAttribute('data-merge-close')){dialog.close();return}if(b.hasAttribute('data-merge-entry')){dialog.close();entrySchool();return}if(b.hasAttribute('data-merge-start')){selected=-1;act({action:'merge_start'});return}if(b.dataset.mergeCell!==undefined){const i=Number(b.dataset.mergeCell),g=state.mergeGame;if(selected<0||selected===i){selected=selected===i?-1:i;message='';draw()}else if(g.board[selected]!==g.board[i]){selected=i;message='서로 다른 그림이에요. 같은 그림 두 개를 골라 주세요.';draw()}else act({action:'merge_move',gameId:g.id,from:selected,to:i})}};
})();
